// These device replies are independent XML fixtures, not generated by the PTZ
// encoder. Include asymmetric ranges to catch hard-coded [-1,1] velocities.
func ptzFixture(t *testing.T, media2, pan, zoom, continuous bool) (*Client, *[]string) {
	t.Helper()
	c := fixtureClient(t, media2)
	original := c.http.Transport
	wire := []string{}
	c.http.Transport = roundTrip(func(r *http.Request) (*http.Response, error) {
		raw, _ := io.ReadAll(r.Body)
		r.Body = io.NopCloser(strings.NewReader(string(raw)))
		s := string(raw)
		wire = append(wire, s)
		switch {
		case strings.Contains(s, "<m:GetServices"):
			ns := media1NS
			if media2 {
				ns = media2NS
			}
			return response(envelope(deviceNS, "GetServices", `<m:Service><m:Namespace>`+ns+`</m:Namespace><m:XAddr>http://192.0.2.10/media</m:XAddr></m:Service><m:Service><m:Namespace>`+ptzNS+`</m:Namespace><m:XAddr>http://192.0.2.10/ptz</m:XAddr></m:Service>`)), nil
		case strings.Contains(s, "<m:GetProfiles"):
			ns := media1NS
			configs := `<tt:VideoSourceConfiguration><tt:SourceToken>source-a</tt:SourceToken></tt:VideoSourceConfiguration><tt:PTZConfiguration token="ptz-a"/>`
			if media2 {
				ns = media2NS
				configs = `<m:Configurations><tt:VideoSource><tt:SourceToken>source-a</tt:SourceToken></tt:VideoSource><tt:PTZ token="ptz-a"/></m:Configurations>`
			}
			return response(envelope(ns, "GetProfiles", `<m:Profiles token="main"><m:Name>Main</m:Name>`+configs+`</m:Profiles><m:Profiles token="sub"><m:Name>Sub</m:Name>`+configs+`</m:Profiles>`)), nil
		case strings.Contains(s, "<m:GetConfigurationOptions"):
			spaces := ""
			pName, pURI, zName, zURI := "RelativePanTiltTranslationSpace", panTranslation, "RelativeZoomTranslationSpace", zoomTranslation
			if continuous {
				pName, pURI, zName, zURI = "ContinuousPanTiltVelocitySpace", panVelocity, "ContinuousZoomVelocitySpace", zoomVelocity
			}
			if pan {
				spaces += fmt.Sprintf(`<tt:%s><tt:URI>%s</tt:URI><tt:XRange><tt:Min>-2</tt:Min><tt:Max>4</tt:Max></tt:XRange><tt:YRange><tt:Min>-3</tt:Min><tt:Max>6</tt:Max></tt:YRange></tt:%s>`, pName, pURI, pName)
			}
			if zoom {
				spaces += fmt.Sprintf(`<tt:%s><tt:URI>%s</tt:URI><tt:XRange><tt:Min>-2</tt:Min><tt:Max>3</tt:Max></tt:XRange></tt:%s>`, zName, zURI, zName)
			}
			return response(envelope(ptzNS, "GetConfigurationOptions", `<m:PTZConfigurationOptions><tt:Spaces>`+spaces+`</tt:Spaces><tt:PTZTimeout><tt:Min>PT0.1S</tt:Min><tt:Max>PT10S</tt:Max></tt:PTZTimeout></m:PTZConfigurationOptions>`)), nil
		case strings.Contains(s, "<m:GetConfiguration"):
			return response(envelope(ptzNS, "GetConfiguration", `<m:PTZConfiguration token="ptz-a"><tt:NodeToken>motor-a</tt:NodeToken></m:PTZConfiguration>`)), nil
		case strings.Contains(s, "<m:GetNode"):
			return response(envelope(ptzNS, "GetNode", `<m:PTZNode token="motor-a"><tt:MaximumNumberOfPresets>9</tt:MaximumNumberOfPresets></m:PTZNode>`)), nil
		case strings.Contains(s, "<m:GetServiceCapabilities"):
			return response(envelope(ptzNS, "GetServiceCapabilities", `<m:Capabilities MoveStatus="true" StatusPosition="true"/>`)), nil
		case strings.Contains(s, "<m:GetPresets"):
			return response(envelope(ptzNS, "GetPresets", `<m:Preset token="gate"><tt:Name>Front gate</tt:Name></m:Preset>`)), nil
		case strings.Contains(s, "<m:SetPreset"):
			return response(envelope(ptzNS, "SetPreset", `<m:PresetToken>new-gate</m:PresetToken>`)), nil
		case strings.Contains(s, "<m:GetStatus"):
			return response(envelope(ptzNS, "GetStatus", `<m:PTZStatus><tt:Position><tt:PanTilt x="0.3" y="0.2" space="pan-space"/><tt:Zoom x="0.6" space="zoom-space"/></tt:Position><tt:MoveStatus><tt:PanTilt>IDLE</tt:PanTilt><tt:Zoom>IDLE</tt:Zoom></tt:MoveStatus></m:PTZStatus>`)), nil
		}
		for _, action := range []string{"ContinuousMove", "RelativeMove", "Stop", "GotoPreset", "RemovePreset"} {
			if strings.Contains(s, "<m:"+action+" ") {
				return response(envelope(ptzNS, action, "")), nil
			}
		}
		return original.RoundTrip(r)
	})
	return c, &wire
}
func TestPTZProfilesMapToSharedMotorAndExactCapabilities(t *testing.T) {
	for _, m2 := range []bool{false, true} {
		c, _ := ptzFixture(t, m2, false, true, true)
		service := "media1"
		if m2 {
			service = "media2"
		}
		a, e := c.PreparePTZ(context.Background(), service, "main", "source-a")
		if e != nil {
			t.Fatal(e)
		}
		b, e := c.PreparePTZ(context.Background(), service, "sub", "source-a")
		if e != nil {
			t.Fatal(e)
		}
		if a.caps.Resource != b.caps.Resource || a.caps.Resource == "" || a.caps.PanTilt || !a.caps.Zoom || !a.caps.Presets {
			t.Fatalf("wrong capabilities %+v", a.caps)
		}
		if _, e = c.PreparePTZ(context.Background(), service, "main", "different-source"); Code(e) != "profile_not_found" {
			t.Fatal("NVR source silently changed", e)
		}
	}
}
func TestPTZContinuousUsesDeviceSpaceAndShortTimeout(t *testing.T) {
	c, w := ptzFixture(t, false, true, true, true)
	target, e := c.PreparePTZ(context.Background(), "media1", "main", "source-a")
	if e != nil {
		t.Fatal(e)
	}
	if e = target.Move(context.Background(), ptzcontrol.Vector{Pan: -.5, Tilt: .5, Zoom: .5}, 800*time.Millisecond); e != nil {
		t.Fatal(e)
	}
	s := (*w)[len(*w)-1]
	for _, want := range []string{`x="-1.00000000"`, `y="3.00000000"`, `x="1.50000000"`, `<m:Timeout>PT0.800S</m:Timeout>`} {
		if !strings.Contains(s, want) {
			t.Fatal("missing", want, s)
		}
	}
	if e = target.Stop(context.Background()); e != nil {
		t.Fatal(e)
	}
}
func TestPTZRelativeOnlyAndFixedCamera(t *testing.T) {
	c, w := ptzFixture(t, false, true, false, false)
	target, e := c.PreparePTZ(context.Background(), "media1", "main", "source-a")
	if e != nil {
		t.Fatal(e)
	}
	if target.caps.ContinuousPanTilt || !target.caps.RelativePanTilt {
		t.Fatal(target.caps)
	}
	if e = target.Move(context.Background(), ptzcontrol.Vector{Pan: .5}, time.Second); e != nil {
		t.Fatal(e)
	}
	if s := (*w)[len(*w)-1]; !strings.Contains(s, "<m:RelativeMove ") || !strings.Contains(s, `x="0.04000000"`) {
		t.Fatal(s)
	}
	if e = target.Move(context.Background(), ptzcontrol.Vector{Zoom: 1}, time.Second); Code(e) != "ptz_operation_unsupported" {
		t.Fatal(e)
	}
	fixed := fixtureClient(t, false)
	v, e := fixed.PreparePTZ(context.Background(), "media1", "main", "source-a")
	if e != nil || v.caps.Resource != "" || v.caps.Reason != "ptz_not_supported" {
		t.Fatal(v, e)
	}
}
func TestPTZPresetsEscapingStatusAndUnknownPreset(t *testing.T) {
	c, w := ptzFixture(t, false, true, true, true)
	target, e := c.PreparePTZ(context.Background(), "media1", "main", "source-a")
	if e != nil {
		t.Fatal(e)
	}
	if id, e := target.SetPreset(context.Background(), "", `Gate <one> & back`); e != nil || id != "new-gate" {
		t.Fatal(id, e)
	}
	if s := (*w)[len(*w)-1]; !strings.Contains(s, `Gate &lt;one&gt; &amp; back`) {
		t.Fatal("XML injection", s)
	}
	if e = target.Preset(context.Background(), "unknown"); Code(e) != "ptz_preset_not_found" {
		t.Fatal(e)
	}
	if e = target.Preset(context.Background(), "gate"); e != nil {
		t.Fatal(e)
	}
	if e = target.RemovePreset(context.Background(), "gate"); e != nil {
		t.Fatal(e)
	}
	st, e := target.Status(context.Background())
	if e != nil || st.Position == nil || *st.Position.Zoom != .6 || st.PanTilt != "IDLE" {
		t.Fatal(st, e)
	}
}

func TestPTZDifferentConfigurationsCanShareOneNode(t *testing.T) {
	c, _ := ptzFixture(t, false, true, true, true)
	original := c.http.Transport
	c.http.Transport = roundTrip(func(r *http.Request) (*http.Response, error) {
		raw, _ := io.ReadAll(r.Body)
		s := string(raw)
		r.Body = io.NopCloser(strings.NewReader(s))
		if strings.Contains(s, "<m:GetConfigurations ") {
			return response(envelope(ptzNS, "GetConfigurations", `<m:PTZConfiguration token="ptz-a"><tt:NodeToken>motor-a</tt:NodeToken></m:PTZConfiguration><m:PTZConfiguration token="ptz-b"><tt:NodeToken>motor-a</tt:NodeToken></m:PTZConfiguration><m:PTZConfiguration token="ptz-c"><tt:NodeToken>motor-c</tt:NodeToken></m:PTZConfiguration>`)), nil
		}
		if strings.Contains(s, "<m:GetProfiles ") {
			return response(envelope(media1NS, "GetProfiles", `<m:Profiles token="main"><tt:VideoSourceConfiguration><tt:SourceToken>source-a</tt:SourceToken></tt:VideoSourceConfiguration><tt:PTZConfiguration token="ptz-a"/></m:Profiles><m:Profiles token="sub"><tt:VideoSourceConfiguration><tt:SourceToken>source-b</tt:SourceToken></tt:VideoSourceConfiguration><tt:PTZConfiguration token="ptz-b"/></m:Profiles><m:Profiles token="other"><tt:VideoSourceConfiguration><tt:SourceToken>source-c</tt:SourceToken></tt:VideoSourceConfiguration><tt:PTZConfiguration token="ptz-c"/></m:Profiles>`)), nil
		}
		return original.RoundTrip(r)
	})
	target, err := c.PreparePTZ(context.Background(), "media1", "main", "source-a")
	if err != nil {
		t.Fatal(err)
	}
	if fmt.Sprint(target.caps.VideoSources) != "[source-a source-b]" {
		t.Fatal(target.caps.VideoSources)
	}
}
func TestPTZContextEvictionProtectsActiveAndRecentTargets(t *testing.T) {
	p := newPTZHTTP()
	defer p.Close()
	for i := 0; i < 128; i++ {
		c, _ := ptzFixture(t, false, true, true, true)
		p.targets[fmt.Sprint(i)] = &preparedPTZ{target: &PTZTarget{client: c}, used: time.Now().Add(-time.Hour), refs: 1}
	}
	p.evictIdleLocked()
	if len(p.targets) != 128 {
		t.Fatal("active target evicted")
	}
	p.targets["0"].refs = 0
	p.targets["0"].used = time.Now()
	p.evictIdleLocked()
	if len(p.targets) != 128 {
		t.Fatal("recent target evicted")
	}
	p.targets["0"].used = time.Now().Add(-time.Minute)
	p.evictIdleLocked()
	if len(p.targets) != 127 || p.targets["0"] != nil {
		t.Fatal("idle target did not expire")
	}
}

func TestPTZHTTPAuthenticationLimitsAndStopPriority(t *testing.T) {
	c, _ := ptzFixture(t, false, true, true, true)
	target, err := c.PreparePTZ(context.Background(), "media1", "main", "source-a")
	if err != nil {
		t.Fatal(err)
	}
	service, err := NewServer(strings.Repeat("k", 32))
	if err != nil {
		t.Fatal(err)
	}
	defer service.Close()
	service.settings.Enabled = true
	key := strings.Repeat("a", 48)
	service.ptz.targets[key] = &preparedPTZ{target: target, used: time.Now()}
	server := httptest.NewServer(service)
	defer server.Close()
	request := func(token string, body any) int {
		raw, _ := json.Marshal(body)
		req, _ := http.NewRequest("POST", server.URL+"/v1/ptz/command", bytes.NewReader(raw))
		req.Header.Set("X-Service-Token", token)
		resp, e := http.DefaultClient.Do(req)
		if e != nil {
			t.Fatal(e)
		}
		defer resp.Body.Close()
		io.Copy(io.Discard, resp.Body)
		return resp.StatusCode
	}
	command := ptzcontrol.Command{Session: "session-111111111111", Sequence: 1, Vector: ptzcontrol.Vector{Pan: 1}, TTLMS: 1500, ExpiresAtMS: time.Now().Add(1500 * time.Millisecond).UnixMilli()}
	body := map[string]any{"context": key, "command": command}
	if code := request("wrong", body); code != 401 {
		t.Fatal(code)
	}
	if code := request(strings.Repeat("k", 32), map[string]any{"context": key, "unknown": true}); code != 400 {
		t.Fatal(code)
	}
	if code := request(strings.Repeat("k", 32), body); code != 200 {
		t.Fatal(code)
	}
	// Exhaust movement slots and disable control; Stop must still have a path.
	for i := 0; i < cap(service.ptz.slots); i++ {
		service.ptz.slots <- struct{}{}
	}
	service.mu.Lock()
	service.settings.Enabled = false
	service.mu.Unlock()
	command.Stop = true
	command.Sequence = 2
	command.Vector = ptzcontrol.Vector{}
	body["command"] = command
	if code := request(strings.Repeat("k", 32), body); code != 200 {
		t.Fatal("Stop blocked", code)
	}
	for i := 0; i < cap(service.ptz.slots); i++ {
		<-service.ptz.slots
	}
}
